// The next 24 hours around a 24-hour clock face, noon at the top and midnight
// at the bottom: the outer ring is the temperature hour by hour in color, the
// bars inside it the chance of rain, the night is shaded from sunset to
// sunrise, and the hand points at now. The ring starts at the hand and runs
// clockwise a whole day round.
import { wordsFor, degrees, celsius, compass, placeClock, hourIndex, dayIndex, clockText, temperatureColor, mix } from './weather'

// The look. On an LCD the colors below. On e-paper with no color (1-bit, or
// 16 greys) black on white: the temperature is how far each hour's slice
// reaches out, the night a black arc, no grey anywhere. On color e-paper the
// same in the Spectra inks, so they print solid. The Contrast setting can
// choose either.
type Look = 'color' | 'mono' | 'inks'
function lookOf(app: FrameOSApp): Look {
  const mode = app.state.contrast || 'auto'
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return 'mono'
  if (mode === 'color') return 'color'
  return app.frame.paper ? 'inks' : 'color'
}
// The six inks of a Spectra panel, as the colors that come through its fit and
// dither as one ink each (tried in the bench's simulator of the panel).
const INK = { black: '#000000', white: '#ffffff', yellow: '#ffff00', red: '#800000', blue: '#0000ff', green: '#008000' }
// A temperature (°C) in one of the inks: cold blue, mild green, warm yellow, hot red.
function inkFor(c: number) {
  return c < 5 ? INK.blue : c < 15 ? INK.green : c < 25 ? INK.yellow : INK.red
}
const COLORS = {
  color: { back: '#0d1117', face: '#1a2331', night: '#0c1018', line: '#2a3442', text: '#e8edf3', muted: '#8693a3', rain: '#4ea3e8', rise: '#f3c969', set: '#e98a5c' },
  mono: { back: '#ffffff', face: '#ffffff', night: '#000000', line: '#000000', text: '#000000', muted: '#000000', rain: '#000000', rise: '#000000', set: '#000000' },
  inks: { back: '#ffffff', face: '#ffffff', night: '#000000', line: '#000000', text: '#000000', muted: '#000000', rain: INK.blue, rise: INK.yellow, set: INK.red },
}

// Text to a width: one line, or two split at a space when one would be too
// small to read. [lines, font size]
function fitLines(text: string, width: number, size: number, least: number): [string[], number] {
  const one = Math.min(size, width / (text.length * 0.56))
  if (one >= least) return [[text], one]
  let cut = -1
  for (let i = 0; i < text.length; i++) {
    if (text[i] === ' ' && (cut < 0 || Math.abs(i - text.length / 2) < Math.abs(cut - text.length / 2))) cut = i
  }
  if (cut < 0) return [[text], one]
  const lines = [text.substring(0, cut), text.substring(cut + 1)]
  const longest = Math.max(lines[0].length, lines[1].length)
  return [lines, Math.min(size, width / (longest * 0.56))]
}

function point(cx: number, cy: number, r: number, turns: number) {
  const a = turns * Math.PI * 2
  return [cx + Math.sin(a) * r, cy - Math.cos(a) * r]
}

// A ring's sector from one turn to another (0 = top, clockwise).
function sector(cx: number, cy: number, inner: number, outer: number, from: number, to: number) {
  const large = to - from > 0.5 ? 1 : 0
  const [x1, y1] = point(cx, cy, outer, from)
  const [x2, y2] = point(cx, cy, outer, to)
  const [x3, y3] = point(cx, cy, inner, to)
  const [x4, y4] = point(cx, cy, inner, from)
  const f = (n: number) => n.toFixed(1)
  return (
    `M${f(x1)} ${f(y1)} A${f(outer)} ${f(outer)} 0 ${large} 1 ${f(x2)} ${f(y2)} ` +
    `L${f(x3)} ${f(y3)} A${f(inner)} ${f(inner)} 0 ${large} 0 ${f(x4)} ${f(y4)} Z`
  )
}

// Where a moment of the place's day sits on the face: noon at the top.
function turnsOf(epochMs: number, offset: number) {
  const d = placeClock(epochMs, offset)
  const hours = d.getUTCHours() + d.getUTCMinutes() / 60
  return (hours - 12) / 24
}

function sunGlyph(x: number, y: number, r: number, color: string, outline: string | null) {
  const rays = []
  for (let i = 0; i < 8; i++) {
    const [x1, y1] = point(x, y, r * 1.45, i / 8)
    const [x2, y2] = point(x, y, r * 2, i / 8)
    rays.push(<line x1={x1} y1={y1} x2={x2} y2={y2} stroke={outline || color} strokeWidth={r * 0.35} strokeLinecap="round" />)
  }
  return (
    <g>
      <circle cx={x} cy={y} r={r} fill={color} stroke={outline || 'none'} strokeWidth={r * 0.3} />
      {rays}
    </g>
  )
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const weather = app.config.weather || {}
  if (!weather.current || !weather.hourly) {
    throw new Error(weather.error || 'No weather yet')
  }
  const look = lookOf(app)
  const paper = look !== 'color'
  const { back: BACK, face: FACE, night: NIGHT, line: LINE, text: TEXT, muted: MUTED, rain: RAIN } = COLORS[look]
  const twelve = app.config.clock === '12h'
  const f = weather.fahrenheit
  const offset = weather.offset || 0
  const now = Date.now()
  const hourly = weather.hourly
  const daily = weather.daily
  const first = Math.max(0, hourIndex(hourly, now))
  const hours = []
  for (let i = first; i < Math.min(hourly.temperature.length, first + 24); i++) hours.push(i)

  // Where the dial goes, and what goes beside it.
  const wide = W >= H * 1.25
  const tall = H >= W * 1.25
  // Nothing a person reads under 13 px, a cap height of 9 (a caption on a
  // 2.8" or the dial's middle on a watch).
  const least = 13
  // The dial's square, leaving the panel at least 40% of the screen (45% on a
  // small one, where the words beside it are at their least size).
  const small = (Math.min(W, H) / 100) * 3.2 < least
  const side = wide ? Math.min(H, W * (small ? 0.55 : 0.6)) : tall ? Math.min(W, H * 0.6) : Math.min(W, H)
  const cx = wide ? side * 0.52 : W / 2
  const cy = tall ? side * 0.52 : H / 2
  const u = side / 100
  const fs = (k: number) => Math.max(u * k, least)
  // On a round panel the hour labels keep clear of the rim (docs/scene-guide.md),
  // and on any panel they stay whole on it.
  const hourSize = fs(3.6)
  const hourHalf = hourSize * 0.28 * (twelve ? 3 : 2)
  const labelRoom = Math.min(cx, cy, W - cx, H - cy) - u * 1.2 - hourSize * 0.75 - hourHalf - 1
  const R = Math.min(context.round === true ? side * 0.38 : side * 0.4, labelRoom / 1.07)
  // A line on paper is two pixels at least: a thinner one is grey at its
  // edges, and grey is what e-paper cannot print.
  const lw = (k: number) => (paper ? Math.max(u * k, 2) : u * k)

  const ringOuter = R
  const ringInner = R * 0.82
  // On paper the night is an arc between the rain and the ring.
  const rainOuter = paper ? R * 0.74 : R * 0.78
  const rainInner = R * 0.6
  const nowTurns = turnsOf(now, offset)

  // Night, from today's sunset to tomorrow's sunrise.
  const today = Math.max(0, dayIndex(daily, now))
  const sunrise = daily.sunrise[today]
  const sunset = daily.sunset[today]
  const riseTurns = turnsOf(sunrise, offset)
  const setTurns = turnsOf(sunset, offset)

  const temps = hours.map((i) => hourly.temperature[i])
  const high = Math.max(...temps)
  const low = Math.min(...temps)
  const highAt = hours[temps.indexOf(high)]
  const lowAt = hours[temps.indexOf(low)]
  // On paper an hour's slice reaches out as far as it is warm.
  const tSpan = Math.max(high - low, f ? 4 : 2)
  const reachOf = (t: number) => (paper ? ringInner + (ringOuter - ringInner) * (0.3 + (0.7 * (t - low)) / tSpan) : ringOuter)

  // An hour's slice of the ring: the first one starts at the hand.
  const slice = (i: number) => {
    const at = hourly.start + i * 3600000
    const from = turnsOf(Math.max(at, now), offset)
    let to = turnsOf(at + 3600000, offset)
    if (to < from) to += 1
    return [from, to]
  }

  const segments = []
  const bars = []
  const gap = 0.0025
  for (const i of hours) {
    const [from, to] = slice(i)
    const c = celsius(hourly.temperature[i], f)
    const fill = look === 'mono' ? INK.black : look === 'inks' ? inkFor(c) : temperatureColor(c)
    segments.push(<path d={sector(cx, cy, ringInner, reachOf(hourly.temperature[i]), from + gap, to - gap)} fill={fill} />)
    const chance = hourly.rainChance[i] ?? 0
    const amount = hourly.precipitation[i] ?? 0
    if (chance > 0) {
      const reach = rainInner + (rainOuter - rainInner) * Math.min(1, chance / 100)
      const middle = (from + to) / 2
      const width = (to - from) * 0.55
      // A chance of rain with none to measure: pale on an LCD, an outline on paper.
      bars.push(
        paper && amount < 0.1 ? (
          <path d={sector(cx, cy, rainInner, reach, middle - width / 2, middle + width / 2)} fill={BACK} stroke={RAIN} strokeWidth={lw(0.35)} />
        ) : (
          <path d={sector(cx, cy, rainInner, reach, middle - width / 2, middle + width / 2)} fill={amount >= 0.1 ? RAIN : mix(RAIN, FACE, 0.45)} />
        ),
      )
    }
  }

  const ticks = []
  for (let h = 0; h < 24; h++) {
    const turns = (h - 12) / 24
    const major = h % 3 === 0
    const [x1, y1] = point(cx, cy, R * 1.02, turns)
    const [x2, y2] = point(cx, cy, R * (major ? 1.07 : 1.045), turns)
    ticks.push(<line x1={x1} y1={y1} x2={x2} y2={y2} stroke={major ? MUTED : LINE} strokeWidth={lw(major ? 0.5 : paper ? 0.25 : 0.35)} strokeLinecap="round" />)
    if (major) {
      const size = hourSize
      const [lx, ly] = point(cx, cy, R * 1.07 + u * 1.2 + size * 0.75, turns)
      const label = twelve ? (h === 0 ? '12a' : h === 12 ? '12p' : h < 12 ? h + 'a' : h - 12 + 'p') : (h < 10 ? '0' : '') + h
      ticks.push(
        <text x={lx} y={ly + size * 0.38} fontFamily="FiraGO" fontWeight={paper ? 600 : 400} fontSize={size} fill={MUTED} textAnchor="middle">
          {label}
        </text>,
      )
    }
  }

  // Labels on the warmest and coldest hours.
  const mark = (i: number, value: number) => {
    const [from, to] = slice(i)
    const [x, y] = point(cx, cy, (ringInner + ringOuter) / 2, (from + to) / 2)
    const size = fs(3.4)
    return (
      <g>
        {paper ? (
          <circle cx={x} cy={y} r={size * 1.05} fill={BACK} stroke={TEXT} strokeWidth={lw(0.35)} />
        ) : (
          <circle cx={x} cy={y} r={size * 1.05} fill={BACK} opacity={0.85} />
        )}
        <text x={x} y={y + size * 0.37} fontFamily="FiraGO" fontWeight={600} fontSize={size} fill={TEXT} textAnchor="middle">
          {degrees(value).replace('°', '')}
        </text>
      </g>
    )
  }

  const [hx, hy] = point(cx, cy, R * 1.05, nowTurns)
  const [hx0, hy0] = point(cx, cy, R * 0.56, nowTurns)
  const [sx, sy] = point(cx, cy, R * 0.5, riseTurns)
  const [ex, ey] = point(cx, cy, R * 0.5, setTurns)
  const current = weather.current
  const clock = (ms: number) => clockText(ms, offset, twelve)
  const wordsY = cy + Math.max(R * 0.32, R * 0.14 + fs(3.6) * 1.25)

  // The facts beside the dial, or under it on a tall screen.
  let panel = null
  if (wide || tall) {
    const totalRain = hours.reduce((sum, i) => sum + (hourly.precipitation[i] ?? 0), 0)
    const wet = hours.filter((i) => (hourly.precipitation[i] ?? 0) >= 0.1)
    let stretches = wet.length ? 1 : 0
    for (let k = 1; k < wet.length; k++) if (wet[k] - wet[k - 1] > 1) stretches++
    const rainLine = wet.length
      ? (stretches === 1
          ? `${clock(hourly.start + wet[0] * 3600000)}–${clock(hourly.start + (wet[wet.length - 1] + 1) * 3600000)}`
          : `On and off from ${clock(hourly.start + wet[0] * 3600000)}`) +
        ` · ${totalRain < 10 ? totalRain.toFixed(1) : Math.round(totalRain)} ${weather.units.precipitation}`
      : Math.max(...hours.map((i) => hourly.rainChance[i] ?? 0)) >= 30
        ? 'A chance, no more'
        : 'None expected'
    const gusty = (current.gusts ?? 0) > (current.wind ?? 0) * 1.3
    const allFacts = [
      ['Warmest', `${degrees(high)} at ${clock(hourly.start + highAt * 3600000)}`],
      ['Coldest', `${degrees(low)} at ${clock(hourly.start + lowAt * 3600000)}`],
      ['Wind', `${compass(current.windDirection ?? 0)} ${Math.round(current.wind ?? 0)} ${weather.units.wind}${gusty ? `, gusts ${Math.round(current.gusts)}` : ''}`],
      ['Sun', `${clock(sunrise)} – ${clock(sunset)}`],
      ['Rain', rainLine],
    ]
    const px = wide ? side * 1.1 : W * 0.08
    const pw = wide ? W - px - side * 0.06 : W * 0.84
    // Beside the dial one column; under it two.
    const columns = wide ? 1 : 2
    const caption = fs(3.2)
    const colWidth = pw / columns
    // The heading on one line, or the place over "next 24 hours" where the
    // column is narrow (a 2.8").
    const [heading, headSize] = fitLines(`${(weather.place || '').toUpperCase()} · NEXT 24 HOURS`, pw, fs(3.4), least)
    // Each fact's value fitted to its column. Beside the dial the column is as
    // tall as the panel: where five facts do not fit it at a readable size,
    // the sun's goes (the dial shows sunrise and sunset).
    const fitted = (list: string[][]) =>
      list.map((fact, j) => {
        // The rain line, last, gets the whole width.
        const width = j === list.length - 1 ? pw : colWidth - (columns > 1 ? u * 3 : 0)
        const [lines, size] = fitLines(fact[1], width, Math.max(u * (columns > 1 ? 4 : 4.6), least * 1.1), least)
        return { name: fact[0], width, lines, size }
      })
    let facts = fitted(allFacts)
    const extraOf = (list: { lines: string[]; size: number }[]) => list.reduce((sum, f) => sum + (f.lines.length - 1) * f.size * 1.1, 0)
    const margin = Math.max(u * 3, 6)
    const roomFor = (list: { lines: string[]; size: number }[]) =>
      (H - margin * 2 - heading.length * headSize * 1.15 - extraOf(list) - caption * 1.3 - list[list.length - 1].size * 1.3) / (list.length - 0.65)
    const leastRow = caption * 1.4 + least * 1.1 * 1.45
    if (wide && roomFor(facts) < leastRow) facts = fitted(allFacts.filter((fact) => fact[0] !== 'Sun'))
    const row = wide
      ? Math.max(Math.min(H * 0.145, u * 15, roomFor(facts)), Math.min(Math.max(caption * 2.9, leastRow), roomFor(facts)))
      : Math.max(Math.min((H - side * 1.06) / 3.6, u * 16), caption * 2.9)
    // Beside the dial the heading and the facts are centred on it.
    const block = heading.length * headSize * 1.15 + row * (facts.length - 0.65) + extraOf(facts) + caption * 1.3 + facts[facts.length - 1].size * 1.3
    const py = wide ? Math.max(margin, (H - block) / 2) + headSize * 0.85 + (heading.length - 1) * headSize * 1.15 : side * 1.06
    const headTop = py - (heading.length - 1) * headSize * 1.15
    // Each fact under its line; a row with a value on two lines is taller.
    const placed = []
    let rowTop = py + row * 0.35
    for (let k = 0; k < facts.length; k += columns) {
      let extra = 0
      for (let j = k; j < Math.min(facts.length, k + columns); j++) {
        const f = facts[j]
        placed.push({ name: f.name, top: rowTop, left: px + (j - k) * colWidth, width: f.width, lines: f.lines, size: f.size })
        extra = Math.max(extra, (f.lines.length - 1) * f.size * 1.1)
      }
      rowTop += row + extra
    }
    panel = (
      <g>
        {heading.map((text, k) => (
          <text x={px} y={headTop + k * headSize * 1.15} fontFamily="FiraGO" fontWeight={600} fontSize={headSize} fill={MUTED}>
            {text.replace(/^· /, '').replace(/ ·$/, '')}
          </text>
        ))}
        {placed.map(({ name, top, left, width, lines, size }) => {
          return (
            <g>
              <line x1={left} y1={top} x2={left + width} y2={top} stroke={LINE} strokeWidth={lw(paper ? 0.2 : 0.25)} />
              <text x={left} y={top + caption * 1.15} fontFamily="FiraGO" fontWeight={paper ? 600 : 400} fontSize={caption} fill={MUTED}>
                {name}
              </text>
              {lines.map((text, j) => (
                <text x={left} y={top + caption * 1.3 + size * (1.05 + j * 1.1)} fontFamily="FiraGO" fontSize={size} fill={TEXT}>
                  {text}
                </text>
              ))}
            </g>
          )
        })}
      </g>
    )
  }

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <rect width={W} height={H} fill={BACK} />
      {paper ? null : <circle cx={cx} cy={cy} r={R} fill={FACE} />}
      {paper ? (
        <path d={sector(cx, cy, R * 0.765, R * 0.8, setTurns, riseTurns + 1)} fill={NIGHT} />
      ) : (
        <path d={sector(cx, cy, 0.001, R, setTurns, riseTurns + 1)} fill={NIGHT} />
      )}
      {paper ? null : <circle cx={cx} cy={cy} r={rainInner} fill={BACK} opacity={0.55} />}
      <circle cx={cx} cy={cy} r={rainInner} fill="none" stroke={LINE} strokeWidth={lw(0.3)} />
      {paper
        ? null
        : [25, 50, 75].map((p) => (
            <circle cx={cx} cy={cy} r={rainInner + ((rainOuter - rainInner) * p) / 100} fill="none" stroke={LINE} strokeWidth={u * 0.18} />
          ))}
      {bars}
      {segments}
      {ticks}
      {sunGlyph(sx, sy, u * 1.1, COLORS[look].rise, look === 'inks' ? INK.black : null)}
      {look === 'mono' ? sunGlyph(ex, ey, u * 1.1, BACK, TEXT) : sunGlyph(ex, ey, u * 1.1, COLORS[look].set, look === 'inks' ? INK.black : null)}
      {mark(highAt, high)}
      {mark(lowAt, low)}
      <line x1={hx0} y1={hy0} x2={hx} y2={hy} stroke={TEXT} strokeWidth={u * 0.8} strokeLinecap="round" />
      <circle cx={hx} cy={hy} r={u * 1.3} fill={TEXT} />

      <text x={cx} y={cy - R * 0.2} fontFamily="FiraGO" fontWeight={600} fontSize={fs(3.2)} fill={MUTED} textAnchor="middle">
        {clock(now)}
      </text>
      <text x={cx + u * 1.5} y={cy + R * 0.14} fontFamily="FiraGO" fontWeight={paper ? 400 : 300} fontSize={R * 0.42} fill={TEXT} textAnchor="middle">
        {degrees(current.temperature)}
      </text>
      <text x={cx} y={wordsY} fontFamily="FiraGO" fontSize={fs(3.6)} fill={TEXT} textAnchor="middle">
        {wordsFor(current.code)}
      </text>
      <text x={cx} y={wordsY + Math.max(R * 0.12, fs(3.2) * 1.2)} fontFamily="FiraGO" fontSize={fs(3.2)} fill={MUTED} textAnchor="middle">
        {`feels ${degrees(current.feelsLike)}`}
      </text>
      {panel}
    </svg>
  )
}

