// What the weather pictures share: the WMO weather codes in words, a color
// for a temperature, and the place's own clock.

export type Kind = 'clear' | 'partly' | 'cloudy' | 'fog' | 'drizzle' | 'rain' | 'snow' | 'storm'

// [kind, words] for each WMO code Open-Meteo sends.
const CODES: Record<number, [Kind, string]> = {
  0: ['clear', 'Clear'],
  1: ['clear', 'Mostly clear'],
  2: ['partly', 'Partly cloudy'],
  3: ['cloudy', 'Overcast'],
  45: ['fog', 'Fog'],
  48: ['fog', 'Freezing fog'],
  51: ['drizzle', 'Light drizzle'],
  53: ['drizzle', 'Drizzle'],
  55: ['drizzle', 'Heavy drizzle'],
  56: ['drizzle', 'Freezing drizzle'],
  57: ['drizzle', 'Freezing drizzle'],
  61: ['rain', 'Light rain'],
  63: ['rain', 'Rain'],
  65: ['rain', 'Heavy rain'],
  66: ['rain', 'Freezing rain'],
  67: ['rain', 'Freezing rain'],
  71: ['snow', 'Light snow'],
  73: ['snow', 'Snow'],
  75: ['snow', 'Heavy snow'],
  77: ['snow', 'Snow grains'],
  80: ['rain', 'Showers'],
  81: ['rain', 'Showers'],
  82: ['rain', 'Heavy showers'],
  85: ['snow', 'Snow showers'],
  86: ['snow', 'Heavy snow showers'],
  95: ['storm', 'Thunderstorm'],
  96: ['storm', 'Thunderstorm with hail'],
  99: ['storm', 'Thunderstorm with hail'],
}

export function kindOf(code: number): Kind {
  return (CODES[code] || CODES[3])[0]
}

export function wordsFor(code: number): string {
  return (CODES[code] || ['cloudy', 'Unknown'])[1]
}

// Thermal ramp, in °C: violet cold through teal and gold to deep red.
const RAMP: [number, number, number, number][] = [
  [-25, 0x5b, 0x3f, 0x95],
  [-12, 0x3d, 0x6c, 0xb9],
  [-2, 0x4f, 0xa3, 0xd1],
  [6, 0x5f, 0xbf, 0xae],
  [13, 0xa9, 0xcf, 0x6e],
  [19, 0xf1, 0xc4, 0x4b],
  [25, 0xf0, 0x8a, 0x3c],
  [31, 0xd9, 0x4b, 0x3a],
  [40, 0x9e, 0x1f, 0x3f],
]

function hex(value: number) {
  const text = Math.max(0, Math.min(255, Math.round(value))).toString(16)
  return text.length < 2 ? '0' + text : text
}

export function mix(a: string, b: string, t: number) {
  const pa = parseInt(a.substring(1), 16)
  const pb = parseInt(b.substring(1), 16)
  const r = ((pa >> 16) & 255) * (1 - t) + ((pb >> 16) & 255) * t
  const g = ((pa >> 8) & 255) * (1 - t) + ((pb >> 8) & 255) * t
  const bl = (pa & 255) * (1 - t) + (pb & 255) * t
  return '#' + hex(r) + hex(g) + hex(bl)
}

export function celsius(value: number, fahrenheit: boolean) {
  return fahrenheit ? ((value - 32) * 5) / 9 : value
}

export function temperatureColor(celsiusValue: number) {
  if (celsiusValue <= RAMP[0][0]) return '#' + hex(RAMP[0][1]) + hex(RAMP[0][2]) + hex(RAMP[0][3])
  for (let i = 1; i < RAMP.length; i++) {
    const [top, r, g, b] = RAMP[i]
    if (celsiusValue <= top) {
      const [bottom, r0, g0, b0] = RAMP[i - 1]
      const t = (celsiusValue - bottom) / (top - bottom)
      return '#' + hex(r0 + (r - r0) * t) + hex(g0 + (g - g0) * t) + hex(b0 + (b - b0) * t)
    }
  }
  const last = RAMP[RAMP.length - 1]
  return '#' + hex(last[1]) + hex(last[2]) + hex(last[3])
}

// The place's clock: a Date whose UTC fields are the place's wall clock.
export function placeClock(epochMs: number, offsetSeconds: number) {
  return new Date(epochMs + offsetSeconds * 1000)
}

export function two(value: number) {
  return value < 10 ? '0' + value : '' + value
}

export function clockText(epochMs: number, offsetSeconds: number, twelveHour: boolean) {
  const d = placeClock(epochMs, offsetSeconds)
  const h = d.getUTCHours()
  if (twelveHour) {
    return (h % 12 || 12) + ':' + two(d.getUTCMinutes()) + (h < 12 ? ' am' : ' pm')
  }
  return two(h) + ':' + two(d.getUTCMinutes())
}

export const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
export const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
]

// Index of the hour that holds `epochMs` in an hourly series.
export function hourIndex(series: { start: number }, epochMs: number) {
  return Math.floor((epochMs - series.start) / 3600000)
}

// Index of the place's day that holds `epochMs` in a daily series.
export function dayIndex(series: { start: number }, epochMs: number) {
  return Math.floor((epochMs - series.start) / 86400000)
}

export function degrees(value: number) {
  if (value == null || !isFinite(value)) return '–'
  const n = Math.round(value)
  return (n < 0 ? '−' + -n : '' + n) + '°'
}

export function compass(directionDegrees: number) {
  const names = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW']
  return names[Math.round(((directionDegrees % 360) + 360) / 45) % 8]
}
